/*
    215. 数组中的第K个最大元素
    给定整数数组 nums 和整数 k，请返回数组中第 k 个最大的元素。
    请注意，你需要找的是数组排序后的第 k 个最大的元素，而不是第 k 个不同的元素。
    你必须设计并实现时间复杂度为 O(n) 的算法解决此问题。

    示例 1:
    输入: [3,2,1,5,6,4], k = 2
    输出: 5
    
    示例 2:
    输入: [3,2,3,1,2,4,5,5,6], k = 4
    输出: 4
*/

#include <vector>
#include <span>
#include <random>

int findKthLargest(std::span<int> nums, int k)
{
    if(std::empty(nums)){
        return 0;
    }

    size_t left = 0, right = std::size(nums) - 1;
    int pivot = nums[left];
    while (left < right) {
        while (left < right && nums[right] > pivot) {
            --right;
        }
        right -= (left < right && nums[right] == pivot) ? 1 : 0;
        nums[left] = nums[right];
        while (left < right && nums[left] < pivot) {
            ++left;
        }
		left += (left < right && nums[left] == pivot) ? 1 : 0;
        nums[right] = nums[left];
    }
    nums[left] = pivot;
    if(left == k - 1){
        return nums[left];
    }
    else{
        return left > k - 1 ? findKthLargest(nums.first(left), k) : 
            findKthLargest(nums.subspan(left + 1), k - left - 1);
    }
}

int findKthLargest(std::vector<int>& nums, int k)
{
    return findKthLargest(std::span(nums), std::size(nums) - k + 1);
}

